// =====================================================
// 1. REVISION ET AGRÉGATION DES DONNÉES
// =====================================================
const items = $input.all();
const totalAbsences = items.length;

const parEquipe = {};
const absencesCumulees = [];

items.forEach(item => {
  const data = item.json;
  const equipe = data["Administration pointage"] || "Non spécifié";

  parEquipe[equipe] = (parEquipe[equipe] || 0) + 1;

  if (parseInt(data["RN_JOUR"], 10) > 1) {
    absencesCumulees.push(data);
  }
});

// Fonction de nettoyage pour Markdown Telegram V1
const cleanText = (str) => String(str || '').replace(/[*_`\[\]]/g, '');

// =====================================================
// 2. MOTEUR DE CONSTRUCTION DU MESSAGE TELEGRAM
// Limite : 3800 caractères max (Marge de sécurité)
// =====================================================
const MAX_TELEGRAM_LENGTH = 3800;
const TRUNCATED_NOTICE = "\n\n⚠️ *Message tronqué : la liste complète est disponible par e-mail.*";

let textMessage = `📊 *RAPPORT DES ABSENCES NON JUSTIFIÉES*\n`;
textMessage += `📅 Date : ${new Date().toLocaleDateString('fr-FR')}\n`;
textMessage += `🚨 Total absences : *${totalAbsences}*\n\n`;

// Section Répartition par Équipe
textMessage += `📌 *Répartition par Équipe :*\n`;
for (const [equipe, count] of Object.entries(parEquipe)) {
  const lineEquipe = `• ${cleanText(equipe)} : *${count}* salarié(s)\n`;
  if ((textMessage + lineEquipe + TRUNCATED_NOTICE).length < MAX_TELEGRAM_LENGTH) {
    textMessage += lineEquipe;
  }
}

// Section Absences consécutives
if (absencesCumulees.length > 0) {
  const cumulHeader = `\n⚠️ *Absences consécutives (> 1 j) :*\n`;
  if ((textMessage + cumulHeader + TRUNCATED_NOTICE).length < MAX_TELEGRAM_LENGTH) {
    textMessage += cumulHeader;
    for (const sal of absencesCumulees) {
      const lineCumul = `• *${cleanText(sal["Nom et Prénom"])}* (${cleanText(sal["Matricule"])} ) | *${sal["RN_JOUR"]} j*\n`;
      if ((textMessage + lineCumul + TRUNCATED_NOTICE).length < MAX_TELEGRAM_LENGTH) {
        textMessage += lineCumul;
      } else {
        break;
      }
    }
  }
}

// Section Liste Détaillée
const listHeader = `\n📋 *Liste détaillée :*\n`;
let isTruncated = false;

if ((textMessage + listHeader + TRUNCATED_NOTICE).length < MAX_TELEGRAM_LENGTH) {
  textMessage += listHeader;
  for (let index = 0; index < items.length; index++) {
    const d = items[index].json;
    const line = `${index + 1}. *${cleanText(d["Nom et Prénom"])}* | Mat: ${cleanText(d["Matricule"])} (${d["RN_JOUR"]} j)\n`;

    if ((textMessage + line + TRUNCATED_NOTICE).length < MAX_TELEGRAM_LENGTH) {
      textMessage += line;
    } else {
      isTruncated = true;
      break;
    }
  }
} else {
  isTruncated = true;
}

if (isTruncated) {
  textMessage += TRUNCATED_NOTICE;
}

// =====================================================
// 3. CONSTRUCTION DU RAPPORT HTML (POUR EMAIL)
// =====================================================
let htmlMessage = `
<!DOCTYPE html>
<html>
<head>
  <style>
    body { font-family: Arial, sans-serif; color: #333; }
    h2 { color: #d9534f; border-bottom: 2px solid #d9534f; padding-bottom: 5px; }
    table { width: 100%; border-collapse: collapse; margin-top: 15px; }
    th, td { border: 1px solid #ddd; padding: 8px; text-align: left; }
    th { background-color: #f4f4f4; }
    .badge { background-color: #d9534f; color: white; padding: 3px 8px; border-radius: 3px; font-weight: bold; }
  </style>
</head>
<body>
  <h2>📊 RAPPORT DES ABSENCES NON JUSTIFIÉES</h2>
  <p><strong>Date du rapport :</strong> ${new Date().toLocaleDateString('fr-FR')}</p>
  <p><strong>Total d'absences :</strong> <span class="badge">${totalAbsences}</span></p>

  <h3>📌 Répartition par Service</h3>
  <ul>
    ${Object.entries(parEquipe).map(([eq, count]) => `<li><b>${eq} :</b> ${count} salarié(s)</li>`).join('')}
  </ul>

  ${absencesCumulees.length > 0 ? `
  <h3 style="color: #d9534f;">⚠️ Absences consécutives / Cumulées (> 1 jour)</h3>
  <ul>
    ${absencesCumulees.map(sal => `<li><b>${sal["Nom et Prénom"]}</b> (Matricule: ${sal["Matricule"]}) - ${sal["Administration pointage"]} - <b>${sal["RN_JOUR"]} jours</b></li>`).join('')}
  </ul>
  ` : ''}

  <h3>📋 Liste complète</h3>
  <table>
    <thead>
      <tr>
        <th>#</th>
        <th>Matricule</th>
        <th>Nom & Prénom</th>
        <th>Service / Équipe</th>
        <th>Jours</th>
      </tr>
    </thead>
    <tbody>
      ${items.map((item, index) => {
        const d = item.json;
        return `
          <tr>
            <td>${index + 1}</td>
            <td>${d["Matricule"]}</td>
            <td><b>${d["Nom et Prénom"]}</b></td>
            <td>${d["Administration pointage"]}</td>
            <td style="text-align:center;"><b>${d["RN_JOUR"]}</b></td>
          </tr>
        `;
      }).join('')}
    </tbody>
  </table>
</body>
</html>
`;

return [{
  json: {
    totalAbsences,
    textMessage,
    htmlMessage
  }
}];
